import{_ as p,r as s,o,c as i,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"|resize - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[],"relativePath":"2.x/markup/filter-resize.md","filePath":"2.x/markup/filter-resize.md"}'),l={name:"2.x/markup/filter-resize.md"};function u(g,a,k,d,m,h){const e=s("pre-heading"),t=s("post-heading");return o(),i("div",null,[n(e),a[0]||(a[0]=c("h1",null,"|resize",-1)),n(t),a[1]||(a[1]=r(`<p>The <code>|resize</code> filter attempts to resize the provided image source using the provided resizing configuration and outputs a URL to the resized image.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>image.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The filter accepts three arguments: <code>|resize(width, height, options)</code>.</p><p>If the filter can resize the provided image, then a URL to the image resizer (eg: <code>/resize/filename.png</code>) is returned. For subsequent requests, a direct URL to the resized image is returned. If the filter is unable to process the provided image, then it will instead return the original URL unmodified.</p><p>This will resize a banner.jpg media image to 1920 x 1080 ratio.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media<span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">1920</span><span class="token punctuation">,</span> <span class="token number">1080</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>You can also pass a third options argument. This example will crop the image instead.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>crop<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>See the <a href="./../services/resizer.html#oc-resize-parameters">image resizer article</a> for more information on the available <code>options</code> parameters.</p>`,9))])}const z=p(l,[["render",u]]);export{_ as __pageData,z as default};
